package main

import (
	"net/http"
	"text/template"
)

// 用户生成内容页变体1：访客提交自定义模板源码，服务端解析后渲染个人签名
func renderUGC(w http.ResponseWriter, r *http.Request) {
	// 外部输入入口：POST 表单字段 tplSrc 即模板源码本身
	tplSrc := r.FormValue("tplSrc")
	if tplSrc == "" {
		http.Error(w, "missing tplSrc", http.StatusBadRequest)
		return
	}
	// 危险点：Parse 的模板源码完全由用户控制，{{}} 语法将被执行
	tpl, err := template.New("t").Parse(tplSrc)
	if err != nil {
		http.Error(w, "parse error", http.StatusBadRequest)
		return
	}
	data := map[string]string{"Nickname": "visitor", "Bio": "hello"}
	// 渲染结果未经任何转义直接写回 HTTP 响应
	if err := tpl.Execute(w, data); err != nil {
		http.Error(w, "exec error", http.StatusInternalServerError)
		return
	}
}

func main() {
	http.HandleFunc("/ugc/render", renderUGC)
	http.ListenAndServe("127.0.0.1:8080", nil)
}
