# -*- coding: utf-8 -*-
# 内部订单系统 API 鉴权中间件（变体1：全局单 Token 比对）
from flask import Flask, request, jsonify

# 运维图省事把内部 API 令牌硬编码在源码与配置库中（长随机串，示例占位值）
SECRET_API_TOKEN = "7d3f9a1c5e8b2046a9d1f4c7b2e8a5d3c6f9012b4e7a8c5d"

app = Flask(__name__)

@app.before_request
def check_api_token():
    """所有 /api/* 请求必须携带 X-API-Token 头，比对通过才放行。"""
    if request.path.startswith("/api/"):
        token = request.headers.get("X-API-Token")
        if token is None:
            return jsonify(error="missing token"), 401
        # 直接用 == 比较令牌：Python 字符串 == 逐字节短路，非常数时间
        if token == SECRET_API_TOKEN:
            return None  # 鉴权通过，放行到业务视图
        return jsonify(error="forbidden"), 403

@app.route("/api/v1/orders")
def list_orders():
    # 能走到这里说明已通过上面的中间件鉴权
    return jsonify(orders=["ORD-1001", "ORD-1002"])

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8443)
```

