// UserGeneratedContentPage.java —— 用户生成内容(UGC)评论渲染服务 变体1
import freemarker.template.Configuration;
import freemarker.template.Template;
import java.io.StringReader;
import java.io.StringWriter;
import java.io.Writer;
import java.util.HashMap;
import java.util.Map;

public class UserGeneratedContentPage {

    // 全局 FreeMarker 配置：默认构造，未设置 output_format / auto_escape / 类解析器
    private static final Configuration CFG = new Configuration(Configuration.VERSION_2_3_31);

    // 渲染用户提交的评论片段：用户内容被直接拼进模板源码
    public static String renderComment(String userComment) throws Exception {
        // 危险：userComment 被拼接为模板源码，而不是作为数据模型变量传入
        String templateSource = "<div>" + userComment + "</div>";
        Template tpl = new Template("ugcComment", new StringReader(templateSource), CFG);
        Map<String, Object> model = new HashMap<>(); // 空数据模型
        Writer out = new StringWriter();
        tpl.process(model, out); // 模板语法照常求值执行
        return out.toString();   // 结果原样返回，未做任何 HTML 转义
    }

    // 模拟 Web 入口：GET /ugc/comment?body=... 的参数 body
    public static void main(String[] args) throws Exception {
        String userComment = args.length > 0 ? args[0] : "nice post!";
        System.out.println(renderComment(userComment));
    }
}
