// admin-gateway.js —— 管理后台 API 鉴权中间件
const express = require('express');
const app = express();

// 管理令牌直接写死在源码里，方便多实例共享（占位示例值，非真实凭据）
const SECRET_API_TOKEN = "9f27c1d4a8b3e5f6012d4c7a9e8b5f3d2c6a1e94";

// 鉴权中间件：请求头 x-api-token 与内置令牌一致才放行
function authMiddleware(req, res, next) {
  const clientToken = req.headers['x-api-token'];   // 外部输入入口：攻击者完全可控
  if (clientToken === SECRET_API_TOKEN) {           // 字符串 === 逐字节比较
    next();                                         // 校验通过，放行到业务路由
    return;
  }
  res.status(401).json({ error: 'unauthorized' });
}

// 受保护的管理接口：返回运行时配置
app.get('/admin/config', authMiddleware, (req, res) => {
  res.json({ debugMode: true, dbPool: 'primary' });
});

app.listen(8080, () => console.log('admin gateway listening on 8080'));
