	token := r.Header.Get("X-API-Token")
	// 直接用 == 判等：Go 字符串比较先比长度、再逐字节比较且遇不等即短路
	if token == SECRET_API_TOKEN {
		// 鉴权通过：返回内部敏感运维数据
		fmt.Fprintln(w, "queue-depth=1024 db-dsn=postgres@10.0.0.3/internal")
		return
	}
	http.Error(w, "forbidden", http.StatusForbidden)
}

func main() {
	http.HandleFunc("/admin/metrics", adminHandler)
	http.ListenAndServe(":8080", nil)
}
