// OrderQueryServlet.java —— 订单查询接口 变体1
import java.io.IOException;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class OrderQueryServlet extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        response.setContentType("text/plain;charset=UTF-8");
        // 外部输入入口：GET 参数 orderId 未做任何校验
        String oid = request.getParameter("orderId");
        try {
            Connection conn = DriverManager.getConnection(
                    "jdbc:mysql://localhost:3306/shop", System.getenv("DB_USER"), System.getenv("DB_PASS"));
            Statement stmt = conn.createStatement();
            // 漏洞点：oid 直接字符串拼接到 SQL
            stmt.execute("SELECT * FROM orders WHERE id='" + oid + "'");
            ResultSet rs = stmt.getResultSet();
            while (rs.next()) {
                response.getWriter().println(rs.getString("item") + " | " + rs.getBigDecimal("amount"));
            }
            conn.close();
        } catch (Exception e) {
            // 漏洞点：异常消息原样回显给客户端
            response.getWriter().println(e.getMessage());
        }
    }
}
