import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;

/** API 鉴权中间件：校验 X-Api-Token 请求头，通过后放行内部敏感接口 */
public class ApiAuthMiddleware implements HttpHandler {

    // 硬编码的 API 令牌（示例占位长随机串，非真实凭据）
    private static final String SECRET_API_TOKEN =
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b8550f";

    @Override
    public void handle(HttpExchange exchange) throws IOException {
        // 外部输入入口：攻击者完全可控的请求头
        String token = exchange.getRequestHeaders().getFirst("X-Api-Token");
        if (token == null) {
            exchange.sendResponseHeaders(401, -1); // 缺少令牌直接拒绝
            return;
        }
        // String.equals 逐字节短路比较，非常数时间
        if (token.equals(SECRET_API_TOKEN)) {
            byte[] body = "INTERNAL_PAYMENT_RECORDS:account=A-1024,amount=88000".getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().set("Content-Type", "text/plain");
            exchange.sendResponseHeaders(200, body.length);
            OutputStream os = exchange.getResponseBody();
            os.write(body);
            os.close();
        } else {
            exchange.sendResponseHeaders(403, -1); // 令牌错误拒绝
        }
    }
}
