const express = require('express');
const ejs = require('ejs');
const app = express();
app.set('view engine', 'ejs');
app.use(express.urlencoded({ extended: false }));

// views/ugc_shell.ejs 骨架模板内容：
//   <div class="ugc"><h3><%= pageTitle %></h3>
//   <div class="body"><%- body %></div>
//   <p>欢迎 <%- visitor %></p></div>

// UGC 页面（变体1）：用户可提交自定义 ejs 模板串，保存后由服务端渲染
const ugcStore = {};

// 外部输入入口：保存用户提交的模板串
app.post('/ugc/save', (req, res) => {
  ugcStore[req.body.pageId] = req.body.tpl; // 模板源码原样存储，无过滤
  res.send('saved');
});

// 渲染用户模板页：模板串先被 compile 执行，产物再经 <%- %> 输出
app.get('/ugc/view', (req, res) => {
  const tpl = ugcStore[req.query.pageId] || ''; // 用户可控模板串（数据流起点）
  const body = ejs.render(tpl, {}); // 危险：用户串被当作模板源码 compile 执行，可 RCE
  app.render('ugc_shell', {
    pageTitle: req.query.title || 'UGC Page',
    body: body, // <%- body %> 输出未转义
    visitor: req.query.visitor || 'guest' // <%- visitor %> 输出未转义
  }, (err, html) => {
    if (err) return res.status(500).send('render error');
    res.send(html);
  });
});

app.listen(3000);
```

