package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"os"

	_ "github.com/go-sql-driver/mysql"
)

var db *sql.DB

// handleOrderQuery 订单查询接口：GET /order?id=xxx
func handleOrderQuery(w http.ResponseWriter, r *http.Request) {
	oid := r.URL.Query().Get("id") // 外部输入入口：GET 参数未过滤直接进 SQL
	// 字符串拼接构造查询，oid 可携带 ' OR '1'='1 等注入载荷
	rows, err := db.Query("SELECT * FROM orders WHERE id='" + oid + "'")
	if err != nil {
		// 底层驱动错误原样回显，泄露 SQL 片段/表名/数据库版本
		http.Error(w, err.Error(), 500)
		return
	}
	defer rows.Close()
	out := []map[string]string{}
	for rows.Next() {
		var id, item string
		_ = rows.Scan(&id, &item)
		out = append(out, map[string]string{"id": id, "item": item})
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(out)
}

func main() {
	db, _ = sql.Open("mysql", os.Getenv("DB_DSN")) // 连接串取自环境变量
	http.HandleFunc("/order", handleOrderQuery)
	http.ListenAndServe(":8080", nil)
}
